// single-item input: one Settings row, and the holiday list is fetched once.
//
// Fails OPEN on purpose. If date.nager.at is unreachable this sends anyway and
// says so in the digest. Failing closed would let a dead endpoint silently stop
// every collection in the business, and nobody would notice for weeks - a far
// more expensive failure than one chase landing on a bank holiday.
const cfg = $('Settings').first().json;
const rows = $('Look Up Public Holidays').all().map((i) => i.json);

const today = String($now.toISODate());
const weekday = $now.weekday; // Luxon: 1 = Monday .. 7 = Sunday

const workdays = String(cfg.working_days || '1,2,3,4,5')
  .split(',').map((d) => Number(d.trim())).filter((d) => d >= 1 && d <= 7);

// n8n splits a JSON array response into one item per element, so a year of
// holidays arrives as 14 separate items rather than as one array. Measured live
// on 2026-08-26: reading $input.first() here gave a single holiday object, the
// Array.isArray check failed, the workflow decided the lookup was broken and
// failed open - so the holiday feature silently did nothing on a run where every
// node was green.
let holidays = [];
let lookup_ok = false;
if (rows.length === 1 && Array.isArray(rows[0])) {
  holidays = rows[0];
  lookup_ok = true;
} else if (rows.length === 1 && rows[0] && Array.isArray(rows[0].body)) {
  holidays = rows[0].body;
  lookup_ok = true;
} else if (rows.length && rows[0] && rows[0].date) {
  holidays = rows;
  lookup_ok = true;
}

// A UK holiday can be Scotland-only. Checked live against GB on 2026-08-26:
// 2 January is ["GB-SCT"] and St Patrick's Day is ["GB-NIR"]. Treating either as
// national silences a whole day of chasing for clients in England.
const region = String(cfg.region_code || '').trim().toUpperCase();
let holiday_name = '';
for (const h of holidays) {
  if (!h || String(h.date) !== today) continue;
  const national = h.global === true || !Array.isArray(h.counties) || !h.counties.length;
  const mine = national
    || (region && h.counties.map((c) => String(c).toUpperCase()).indexOf(region) !== -1);
  if (mine) { holiday_name = String(h.localName || h.name || 'public holiday'); break; }
}

const is_workday = workdays.indexOf(weekday) !== -1;

let blocked_by = '';
if (!is_workday) blocked_by = 'today is not one of your working days';
else if (holiday_name) blocked_by = holiday_name;

return [{ json: {
  today,
  weekday,
  send_today: is_workday && !holiday_name,
  blocked_by,
  holiday_name,
  holiday_lookup_ok: lookup_ok,
  region_checked: region || '(none set - national holidays only)',
}}];

// Both sides are read by name: `Read The Chase Log` sits in between and its
// output replaces the item, so $input here is the chase log, not the invoices.
const cfg = $('Settings').first().json;
const rows = $('Read The Ledger').all()
  .map((i) => i.json)
  .filter((r) => r && Object.keys(r).length);

// The chase history lives in an n8n Data Table, never in the invoice sheet.
// That sheet is somebody's accounting export and an automation writing into it
// is how a ledger quietly stops reconciling. The one thing a human can still
// set by hand there is `hold_until`, which is read below and always wins.
const log = {};
for (const item of $('Read The Chase Log').all()) {
  const row = item.json || {};
  const key = String(row.invoice_no || '').trim();
  if (key) log[key] = row;
}

// `03/04/2026` is 3 April in the UK and 4 March in the US. Guessing moves every
// due date by up to eleven months and starts chasing people who are not late,
// so the order is configured rather than inferred, and a date that will not
// parse is reported instead of silently treated as today.
const order = String(cfg.date_order || 'DMY').trim().toUpperCase();

function dayNumber(v) {
  const s = String(v == null ? '' : v).trim();
  if (!s) return null;
  let m = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/);
  if (m) return Date.UTC(Number(m[1]), Number(m[2]) - 1, Number(m[3])) / 86400000;
  m = s.match(/^(\d{1,2})[\/.\-](\d{1,2})[\/.\-](\d{4})/);
  if (m) {
    const a = Number(m[1]);
    const b = Number(m[2]);
    const day = order === 'MDY' ? b : a;
    const month = order === 'MDY' ? a : b;
    return Date.UTC(Number(m[3]), month - 1, day) / 86400000;
  }
  return null;
}

function numberOf(v) {
  const cleaned = String(v == null ? '' : v).replace(/[^0-9.\-]/g, '');
  const n = Number(cleaned);
  return isFinite(n) ? n : 0;
}

function pick(row, names) {
  for (const wanted of names) {
    const hit = Object.keys(row).find((k) => k.trim().toLowerCase() === wanted);
    if (hit && row[hit] !== '' && row[hit] != null) return row[hit];
  }
  return '';
}

const PAID = ['paid', 'settled', 'complete', 'completed', 'closed'];
const todayNum = dayNumber($now.toISODate());

// The ledger already knows who has paid eleven times without being asked. That
// is a tone input and it needs no extra column - it is derivable from the rows
// that are already sitting there.
const history = {};
for (const r of rows) {
  const email = String(pick(r, ['client_email', 'email'])).trim().toLowerCase();
  if (!email) continue;
  const status = String(pick(r, ['status'])).trim().toLowerCase();
  const h = history[email] || (history[email] = { paid: 0, total: 0 });
  h.total += 1;
  if (PAID.indexOf(status) !== -1) h.paid += 1;
}

// Formatted here so the prompt gets "GBP 4,250.00" rather than "GBP 4250". The
// model repeats whatever it is given, and a payment reminder quoting an
// unformatted number reads like a machine wrote it - which is the one thing a
// chase email cannot afford to look like.
const symbol = String(cfg.currency_symbol || '#');
function display(v) {
  return symbol + Number(v || 0).toFixed(2).replace(/\B(?=(\d{3})+(?!\d))/g, ',');
}

const gentle = Number(cfg.days_gentle || 3);
const firm = Number(cfg.days_firm || 14);
const finalDays = Number(cfg.days_final || 30);
const minGap = Number(cfg.min_gap_days || 5);
const maxChases = Number(cfg.max_chases || 4);

const out = [];
for (const r of rows) {
  const invoice_no = String(pick(r, ['invoice_no', 'invoice', 'number', 'ref'])).trim();
  const client_email = String(pick(r, ['client_email', 'email'])).trim();
  const status = String(pick(r, ['status'])).trim().toLowerCase();
  if (!invoice_no || !client_email) continue;
  if (PAID.indexOf(status) !== -1) continue;

  const client_name = String(pick(r, ['client_name', 'client', 'name'])).trim();
  const amount = numberOf(pick(r, ['amount', 'total', 'value']));
  const dueRaw = pick(r, ['due_date', 'due', 'payment_due']);
  const dueNum = dayNumber(dueRaw);

  if (dueNum === null) {
    out.push({ json: {
      invoice_no, client_email, amount,
      client_name: client_name || client_email,
      due_date: String(dueRaw),
      days_overdue: 0,
      stage: 'unknown',
      chase_count: 0,
      invoices_paid_before: 0,
      is_long_standing: false,
      chase_now: false,
      hold_reason: 'due date could not be read - check date_order in Settings',
    }});
    continue;
  }

  const days_overdue = todayNum - dueNum;
  if (days_overdue < gentle) continue; // not late enough to be worth an email

  const seen = log[invoice_no] || {};
  const chase_count = numberOf(seen.chase_count);
  const lastNum = dayNumber(seen.last_chased);
  const holdNum = dayNumber(pick(r, ['hold_until', 'hold']));
  const since_last = lastNum === null ? 9999 : todayNum - lastNum;

  let stage = 'nudge';
  if (days_overdue >= finalDays) stage = 'final';
  else if (days_overdue >= firm) stage = 'firm';

  let chase_now = true;
  let hold_reason = '';
  if (holdNum !== null && holdNum >= todayNum) {
    chase_now = false;
    hold_reason = 'held by hand in the sheet until ' + String(pick(r, ['hold_until', 'hold']));
  } else if (chase_count >= maxChases) {
    chase_now = false;
    hold_reason = 'already chased ' + chase_count + ' times - this one needs a phone call';
  } else if (since_last < minGap) {
    chase_now = false;
    hold_reason = 'chased ' + since_last + ' day(s) ago, minimum gap is ' + minGap;
  }

  const h = history[client_email.toLowerCase()] || { paid: 0, total: 0 };
  out.push({ json: {
    invoice_no,
    client_name: client_name || client_email,
    client_email,
    amount,
    amount_display: display(amount),
    due_date: String(dueRaw),
    days_overdue,
    stage,
    chase_count,
    chase_now,
    hold_reason,
    invoices_paid_before: h.paid,
    is_long_standing: h.paid >= 3,
  }});
}

// A filtering node that can emit nothing ends the branch, and the digest below
// would then never run on exactly the days there is good news to report.
if (!out.length) {
  out.push({ json: { marker: true, chase_now: false, hold_reason: 'nothing is overdue today' } });
}
return out;

// Reads both sides by name. `Look For Their Replies` runs executeOnce and its
// output replaces the invoices, so $input here is a list of emails.
const invoices = $('Find The Overdue Ones').all().map((i) => i.json);
const messages = $('Look For Their Replies').all().map((i) => i.json);

function headerOf(msg, name) {
  const target = name.toLowerCase();
  const payload = msg && msg.payload;
  const headers = (payload && payload.headers) || (msg && msg.headers) || [];
  if (Array.isArray(headers)) {
    for (const h of headers) {
      if (h && String(h.name || '').toLowerCase() === target) return String(h.value || '');
    }
  }
  if (msg && msg[name]) return String(msg[name]);
  if (msg && msg[target]) return String(msg[target]);
  return '';
}

// One search covers every client, so this is address matching rather than
// another API call per invoice. Gmail's From is "Name <user@example.com>", so a plain
// equality check against the address finds nothing at all.
const seen = [];
for (const m of messages) {
  if (!m || (!m.id && !m.payload && !m.snippet)) continue;
  const from = headerOf(m, 'From').toLowerCase();
  const inner = from.match(/<([^>]+)>/);
  seen.push({
    address: (inner ? inner[1] : from).trim(),
    from_raw: headerOf(m, 'From'),
    subject: headerOf(m, 'Subject'),
    snippet: String(m.snippet || '').slice(0, 220),
  });
}

const out = [];
for (const inv of invoices) {
  const email = String(inv.client_email || '').trim().toLowerCase();
  const hit = email ? seen.find((s) => s.address === email) : null;

  if (hit && inv.chase_now) {
    // Deliberately not parsing what they said. "I will pay next week" and "I am
    // disputing this" both mean stop, and telling them apart with a regex is how
    // an automation emails a customer who is already annoyed. The message goes
    // in the digest and a person decides.
    out.push({ json: Object.assign({}, inv, {
      chase_now: false,
      replied: true,
      hold_reason: 'they emailed you back - read it before chasing again',
      reply_subject: hit.subject,
      reply_snippet: hit.snippet,
      reply_from: hit.from_raw,
    })});
  } else {
    out.push({ json: Object.assign({}, inv, { replied: !!hit }) });
  }
}

if (!out.length) {
  out.push({ json: { marker: true, chase_now: false, hold_reason: 'nothing is overdue today' } });
}
return out;

parameters.text:
=You are writing a payment reminder for {{ $('Settings').first().json.business_name }}, signed by {{ $('Settings').first().json.sender_name }}.

First line must be exactly: SUBJECT: <the subject line>
Then a blank line, then the body. Plain text only - no markdown, no headings, no placeholders in square brackets.

The facts, and the only facts you may state:
- Client: {{ $json.client_name }}
- Invoice number: {{ $json.invoice_no }}
- Amount: {{ $json.amount_display }}
- Due date: {{ $json.due_date }}
- Days past due: {{ $json.days_overdue }}
- Reminders already sent about this invoice: {{ $json.chase_count }}
- Invoices this client has already paid: {{ $json.invoices_paid_before }}
- Stage: {{ $json.stage }}

Tone rules, which are the point of the whole thing:
- nudge: warm and brief, assume it is an oversight, four sentences at most.
- firm: direct about the amount and how late it is, still polite, ask for a payment date.
- final: clear that this is the last reminder before it is escalated. No threats, no legal language, and one sentence on what happens next.
- If they have paid three or more times before, acknowledge it in a way that earns goodwill. They are a good client having a bad month, not a debtor.

Never invent a conversation, a phone call, a promise, a late fee, a payment link or a date that is not listed above.
Never apologise for sending the reminder. Never write 'kindly', 'gentle reminder' or 'per my last email'.
Sign off with the sender name only - no signature block, no address, no footer.

