// single-item input: one invoice per loop iteration.
//
// A prompt is a request; this is the guarantee. The two failure modes that
// actually reach a client are an invented number and an invented promise - "as
// we discussed on Tuesday" when there was no Tuesday - so anything left in the
// draft that the ledger does not back is stripped, and an email that lost its
// invoice number is replaced wholesale rather than sent.
const cfg = $('Settings').first().json;
const inv = $('Loop Over Invoices').first().json;
const raw = $input.first().json || {};

const symbol = String(cfg.currency_symbol || '#');
const amount = Number(inv.amount || 0);
const money = symbol + amount.toFixed(2).replace(/\B(?=(\d{3})+(?!\d))/g, ',');

let body = String(raw.text || raw.response || raw.output || '').trim();

// The model is asked for SUBJECT: on line one. When it obliges, split it off;
// when it does not, build the subject here rather than send a body with a stray
// header line sitting at the top of it.
let subject = '';
const firstBreak = body.indexOf('\n');
const firstLine = firstBreak === -1 ? body : body.slice(0, firstBreak);
if (firstLine.toLowerCase().indexOf('subject:') === 0) {
  subject = firstLine.slice(firstLine.indexOf(':') + 1).trim();
  body = body.slice(firstBreak === -1 ? body.length : firstBreak + 1).trim();
}
if (!subject) {
  subject = inv.stage === 'final'
    ? 'Final reminder: invoice ' + inv.invoice_no + ' (' + money + ')'
    : 'Invoice ' + inv.invoice_no + ' - ' + money + ' outstanding';
}

body = body.replace(/\*\*([^*\n]+)\*\*/g, '$1').replace(/^#+\s*/gm, '');

// Markdown link syntax survives into a plain-text email as literal brackets, and
// a placeholder the model invented is worse than no link at all.
body = body.replace(/\[([^\]]+)\]\((https?:[^)]+)\)/g, '$1: $2');
body = body.replace(/\[[A-Z][A-Za-z ]{2,30}\]/g, '').replace(/\{\{[^}]*\}\}/g, '');
body = body.replace(/[ \t]+\n/g, '\n').trim();

const bare = amount.toFixed(2).replace(/\.00$/, '');
const problems = [];
if (body.indexOf(inv.invoice_no) === -1) problems.push('lost the invoice number');
if (body.replace(/,/g, '').indexOf(bare) === -1) problems.push('lost the amount');
if (body.length < 60) problems.push('too short to send');

if (problems.length) {
  body = 'Hi ' + (inv.client_name || 'there') + ',\n\n'
    + 'A quick reminder that invoice ' + inv.invoice_no + ' for ' + money
    + ' was due on ' + inv.due_date + ' and is now ' + inv.days_overdue
    + ' days past its due date.\n\n'
    + 'If it is already on its way, thank you - please ignore this. If something '
    + 'is holding it up, reply here and we will sort it out.\n\n'
    + 'Best regards,\n' + String(cfg.sender_name || cfg.business_name || '');
}

const dry = String(cfg.dry_run) === 'true' || cfg.dry_run === true;

return [{ json: Object.assign({}, inv, {
  subject,
  body,
  money,
  drafted: true,
  used_fallback: problems.length > 0,
  fallback_reason: problems.join('; '),
  dry_run: dry,
  // The IF below reads this rather than negating dry_run in an expression, so
  // the branch label in the canvas says what it does.
  send_for_real: !dry,
  // The ledger columns travel on the same item, so the sheet update needs no
  // second source and cannot drift from what was actually sent.
  last_chased: String($now.toISODate()),
  chase_count: Number(inv.chase_count || 0) + 1,
  status: 'chased',
})}];

// Runs off the loop's `done` output. $('Check What It Wrote').all() would give
// only the final iteration - inside a Split In Batches, all() is scoped to the
// most recent run, which is one invoice.
const cfg = $('Settings').first().json;
const day = $('Is Today A Sending Day?').first().json;
const decided = $('Who Already Replied').all()
  .map((i) => i.json)
  .filter((r) => r && !r.marker);
// Held invoices come back round the loop too, so the sent list is the ones that
// reached the drafting stage - not simply everything the done output carries.
const sent = $input.all().map((i) => i.json).filter((r) => r && r.drafted);

const symbol = String(cfg.currency_symbol || '#');
function money(n) {
  return symbol + Number(n || 0).toFixed(2).replace(/\B(?=(\d{3})+(?!\d))/g, ',');
}

const outstanding = decided.reduce((t, r) => t + Number(r.amount || 0), 0);
const held = decided.filter((r) => !r.chase_now && r.hold_reason);
const replied = held.filter((r) => r.replied);
const dry = String(cfg.dry_run) === 'true' || cfg.dry_run === true;

const lines = [];
lines.push(dry
  ? ':eyes: *Invoice chase - DRY RUN, nothing was sent*'
  : ':envelope: *Invoice chase*');
lines.push(money(outstanding) + ' outstanding across ' + decided.length
  + ' overdue invoice(s).');

if (sent.length) {
  lines.push('');
  lines.push(dry ? '*Would have gone out*' : '*Sent*');
  for (const r of sent.slice(0, 12)) {
    lines.push('- ' + r.client_name + ' | ' + r.invoice_no + ' | ' + money(r.amount)
      + ' | ' + r.days_overdue + 'd late | _' + r.stage + '_'
      + (r.used_fallback ? ' (fallback wording: ' + r.fallback_reason + ')' : ''));
  }
  if (sent.length > 12) lines.push('- ...and ' + (sent.length - 12) + ' more');
} else {
  lines.push('');
  lines.push('Nothing was sent today.');
}

if (replied.length) {
  lines.push('');
  lines.push('*Held - they wrote back, read this before chasing again*');
  for (const r of replied.slice(0, 6)) {
    lines.push('- ' + r.client_name + ' | ' + r.invoice_no + ' | ' + money(r.amount));
    lines.push('  > ' + String(r.reply_snippet || '').replace(/\n/g, ' '));
  }
}

const other = held.filter((r) => !r.replied);
if (other.length) {
  lines.push('');
  lines.push('*Held for other reasons*');
  for (const r of other.slice(0, 8)) {
    lines.push('- ' + r.client_name + ' | ' + r.invoice_no + ' - ' + r.hold_reason);
  }
}

if (!day.holiday_lookup_ok) {
  lines.push('');
  lines.push(':warning: The public holiday lookup failed, so today was treated as a '
    + 'working day. Chases may have gone out on a holiday.');
}

return [{ json: {
  message: lines.join('\n'),
  sent_count: sent.length,
  held_count: held.length,
  outstanding,
}}];
